'use strict';
const test=require('node:test');const assert=require('node:assert/strict');const fs=require('node:fs');const path=require('node:path');
const {record,env,run,job}=require('./fixtures.cjs');const {canonical,hash,validate,PhaseSession}=require('./schema.cjs');const {environmentContext,persistReceipt}=require('./backend.cjs');const {childEnvironment,ackFor}=require('./index.cjs');
const ROOT=process.env.RUNNER_TEMP??process.env.TMPDIR;assert.ok(typeof ROOT==='string'&&path.isAbsolute(ROOT));if(process.platform==='darwin')assert.ok(ROOT.startsWith('/Volumes/CodexE1Work/tmp'));
function fake(directory,damage){
 let id=99001,raw,nativeArtifact,uploadCalls=0,readbacks=0,queries=[];
 const artifact={async uploadArtifact(name,files,root,options){uploadCalls++;assert.equal(root,directory);assert.equal(options.retentionDays,90);assert.equal(options.compressionLevel,0);assert.equal(files.length,1);raw=fs.readFileSync(files[0]);if(damage==='transport')throw new Error('PUBLIC_SENTINEL_SIGNED_URL_REASON');nativeArtifact={id,name,size_in_bytes:500,digest:'sha256:'+'7'.repeat(64),expired:false,expires_at:new Date(Date.now()+89*86400000).toISOString(),workflow_run:{id:12345,repository_id:1071436278,head_repository_id:1071436278,head_branch:'main',head_sha:'a'.repeat(40)}};return {id,size:500,digest:'7'.repeat(64)};},async downloadArtifact(given,options){readbacks++;assert.equal(given,id);assert.equal(options.expectedHash,nativeArtifact.digest);if(damage==='download')throw new Error('PUBLIC_SENTINEL_DOWNLOAD_REASON');fs.writeFileSync(path.join(options.path,'receipt.json'),damage==='body'?Buffer.from('{}'):raw);if(damage==='extra')fs.writeFileSync(path.join(options.path,'extra'),'extra');return {downloadPath:options.path,digestMismatch:damage==='zip-digest'};}};
 const native=async route=>{queries.push(route);if(route.includes('/artifacts/')){const a=structuredClone(nativeArtifact);if(damage==='artifact-id')a.id++;if(damage==='foreign-producer')a.workflow_run.id++;return a;}if(route.includes('/jobs/')){const j=job();if(damage==='job-attempt')j.run_attempt++;if(damage==='post-job-drift'&&readbacks)j.runner_id++;if(damage==='step')j.steps[0].name='Other step';return j;}const r=run();if(damage==='SDK')r.referenced_workflows[0].sha='c'.repeat(40);return r;};
 return {artifact,native,get uploads(){return uploadCalls;},get readbacks(){return readbacks;},queries};
}
async function within(fn){const directory=fs.mkdtempSync(path.join(ROOT,'scanner-artifact-control-'));try{return await fn(directory);}finally{fs.rmSync(directory,{recursive:true,force:true});}}
test('actual backend returns exact durableACK only after nativeID+producer+bodyreadback',()=>within(async directory=>{const f=fake(directory);const r=record();const context=environmentContext(env(),'b'.repeat(40),'777');const ack=await persistReceipt(r,context,{directory,...f});assert.equal(f.uploads,1);assert.equal(f.readbacks,1);assert.equal(f.queries.length,5);assert.equal(ackFor(r,ack),ack);assert.equal(ack.record_readback_sha256,hash(r));assert.equal(ack.exclusive,true);}));
for(const damage of ['transport','download','body','extra','zip-digest','artifact-id','foreign-producer','job-attempt','post-job-drift','step','SDK'])test('actual backend fixed HOLD without secret diagnostics: '+damage,()=>within(async directory=>{const f=fake(directory,damage);await assert.rejects(persistReceipt(record(),environmentContext(env(),'b'.repeat(40),'777'),{directory,...f}),error=>error.message==='DURABLE_RECEIPT_HOLD'&&!String(error.stack).includes('PUBLIC_SENTINEL'));if(['job-attempt','step','SDK'].includes(damage))assert.equal(f.uploads,0);else assert.equal(f.uploads,1);}));
test('strict schemas reject encodedconfig,extra secretfield,wronground,unknowncleanupkind',()=>{for(const mutate of [r=>{r.details.encoded_jit_config='PUBLIC_CONFIG_SENTINEL';},r=>{r.binding.token='PUBLIC_PAT_SENTINEL';},r=>{r.binding.sdk_round=4;},r=>{r.kind='runner_delete';}]){const r=record();mutate(r);assert.throws(()=>validate(r),{message:'PUBLIC_RECEIPT_UNQUALIFIED'});}});
test('session reserves one phase beforeupload; ambiguity cannot retry or changebody',()=>{const s=new PhaseSession(),r=record(),v=s.reserve(r);assert.throws(()=>s.reserve(r));s.accept(v);const next=record('UNKNOWN',v.sha256);const a=s.reserve(next);s.accept(a);assert.throws(()=>s.reserve(next));const ack=record('ACK',a.sha256);assert.equal(validate(ack).record.phase,'ACK');});
test('allthree exact public kinds validate; lease ownerchecksum andphasefields remainclosed',()=>{for(const kind of ['jit','lease','lease_bind']){const r=record('NO_WIRE',null,kind);assert.equal(validate(r).record.kind,kind);}const bad=record('NO_WIRE',null,'lease');bad.details.owner=bad.details.owner.slice(0,-1)+'q';assert.throws(()=>validate(bad));});
test('runtime credentials cannot enter Pythonenvironment, controller manager stayshosted',()=>{const out=childEnvironment({...env(),ACTIONS_RUNTIME_TOKEN:'PUBLIC_RUNTIME_SENTINEL',ACTIONS_RESULTS_URL:'PUBLIC_URL_SENTINEL',GITHUB_TOKEN:'PUBLIC_ARTIFACT_SENTINEL',GH_TOKEN:'PUBLIC_HOST_MANAGER_SENTINEL'});assert.equal(out.GH_TOKEN,'PUBLIC_HOST_MANAGER_SENTINEL');assert.equal(out.SCANNER_RECEIPT_REQUEST_FD,'3');assert.equal(out.SCANNER_RECEIPT_ACK_FD,'4');for(const key of Object.keys(out))assert.ok(!key.startsWith('ACTIONS_')&&!key.startsWith('INPUT_'));assert.equal(out.GITHUB_TOKEN,undefined);});
test('official logger/raw diagnostic output is silenced before dependency import',()=>{
 const {spawnSync}=require('node:child_process');const source=`require(${JSON.stringify(path.join(__dirname,'worker.cjs'))});const core=require(${JSON.stringify(path.join(__dirname,'node_modules/@actions/core'))});core.warning('PUBLIC_SIGNED_URL_SENTINEL');core.info('PUBLIC_REASON_SENTINEL');console.error('PUBLIC_REASON_SENTINEL');process.stdout.write('PUBLIC_RAW_SENTINEL');require('node:fs').writeSync(1,'SAFE_PUBLIC_CONTROL\\n');`;
 const result=spawnSync(process.execPath,['-e',source],{env:{PATH:process.env.PATH,TMPDIR:ROOT},encoding:'utf8',timeout:10000});assert.equal(result.status,0);assert.equal(result.stdout,'SAFE_PUBLIC_CONTROL\n');assert.equal(result.stderr,'');
});
test('artifact worker receives no JITmanager,AGE orAkashcredentials',()=>{const {workerEnvironment}=require('./index.cjs');const base={...env(),ACTIONS_RUNTIME_TOKEN:'PUBLIC_RUNTIME_SENTINEL',GH_TOKEN:'PUBLIC_MANAGER_SENTINEL',SOPS_AGE_KEY:'PUBLIC_AGE_SENTINEL',AKASH_API_KEY:'PUBLIC_AKASH_SENTINEL'};const out=workerEnvironment(base,environmentContext(env(),'b'.repeat(40),'777'));assert.equal(out.ACTIONS_RUNTIME_TOKEN,'PUBLIC_RUNTIME_SENTINEL');assert.equal(out.SCANNER_ARTIFACT_READ_TOKEN,env()['INPUT_GITHUB-TOKEN']);for(const k of ['GH_TOKEN','SOPS_AGE_KEY','AKASH_API_KEY','GITHUB_TOKEN'])assert.equal(out[k],undefined);});
test('artifactwithshortretentioncannotqualifydurableACK',()=>within(async directory=>{const f=fake(directory);const original=f.native;f.native=async route=>{const value=await original(route);if(route.includes('/artifacts/'))value.expires_at=new Date(Date.now()+1000).toISOString();return value;};await assert.rejects(persistReceipt(record(),environmentContext(env(),'b'.repeat(40),'777'),{directory,...f}),{message:'DURABLE_RECEIPT_HOLD'});}));
test('all9phase records match actual frozen Python validator/canonicalSHA byteexact',()=>{const {spawnSync}=require('node:child_process');const records=[];for(const kind of ['jit','lease','lease_bind']){let parent=null;for(const phase of ['NO_WIRE','UNKNOWN','ACK']){const r=record(phase,parent,kind);records.push(r);parent=hash(r);}}const r=spawnSync(process.env.PYTHON??'python3',['-I','-B',path.resolve(__dirname,'tests/generate_schema_records.py')],{input:JSON.stringify(records),env:{PATH:process.env.PATH,TMPDIR:ROOT,PYTHONDONTWRITEBYTECODE:'1'},encoding:'utf8',timeout:10000});assert.equal(r.status,0,r.stderr);const result=JSON.parse(r.stdout);assert.equal(result.length,9);for(let i=0;i<9;i++){assert.equal(result[i].raw,canonical(records[i]));assert.equal(result[i].sha256,validate(records[i]).sha256);}});
test('only fixed isolated uv Python3.13.9 venv is executable, no arbitrary interpreter',()=>{const {pythonPath}=require('./index.cjs');const root=fs.mkdtempSync(path.join(ROOT,'scanner-interpreter-control-'));try{fs.mkdirSync(path.join(root,'scanner-v2-python','bin'),{recursive:true});const binary=path.join(root,'python3.13');fs.writeFileSync(binary,'PUBLIC_NONEXECUTED_BINARY_FIXTURE',{mode:0o500});const executable=path.join(root,'scanner-v2-python','bin','python');fs.symlinkSync(binary,executable);const config=path.join(root,'scanner-v2-python','pyvenv.cfg');fs.writeFileSync(config,'version_info = 3.13.9\ninclude-system-site-packages = false\n',{mode:0o600});assert.equal(pythonPath({RUNNER_TEMP:root},executable),executable);assert.throws(()=>pythonPath({RUNNER_TEMP:root},binary));fs.writeFileSync(config,'version_info = 3.14.0\ninclude-system-site-packages = false\n');assert.throws(()=>pythonPath({RUNNER_TEMP:root},executable));}finally{fs.rmSync(root,{recursive:true,force:true});}});
